import React, { useContext, useEffect, useMemo, useState } from 'react';
import { toJS } from 'mobx';
import { ColProps, Grid, Form, FormInstance } from '@arco-design/web-react';
import { FormItem } from '../interface';
import Field from './Field';
import _ from 'lodash';
import { isVerify, isVerifySync } from 'src/utils/verify';
import { getBuilderItems, getDataBuilder } from './utils';
import { builderItem } from 'src/types/expression';
import Context from '../context';
import { isPromise } from 'src/utils/is';

const { Col } = Grid;
interface FormItemProps {
  formItemProps: FormItem['formItemProps'];
  colProps?: ColProps;
  notCol?: boolean;
  show: any;
  fieldProps?: FormItem['fieldProps'];
  valueType: FormItem['valueType'];
  Render: FormItem['render'];
  preValueChange: FormItem['preValueChange'];
  form: FormInstance;
}
const FormItemRender = ({
  formItemProps,
  fieldProps,
  valueType,
  colProps,
  notCol,
  preValueChange,
  Render,
  form: oForm,
  show,
}: FormItemProps) => {
  const field = formItemProps['field'] as string;
  // console.log('FormItemRender', field, fieldProps)
  const [pField] = useState< string>(() => {
    const paths: any = field.split('.');
    if(paths.length > 1) return paths.slice(0,-1).join('.')
    return "";
  })
  const { form: uForm, formats, ...res } = useContext(Context);
  const form = uForm || oForm;
  const FieldRender = (props: any) => {

    const [vars] = useState<builderItem[]>(() => getBuilderItems(fieldProps))

    const fieldParams = useMemo(() => {
      const values = form.getFields();
      const data = {
        ...(pField? _.get(values, pField) : values),
        formData: oForm.getFields(),
      };
      if(fieldProps && Object.keys(fieldProps).length){
        // const str = JSON.parse(JSON.stringify(fieldProps))
        const params = getDataBuilder(fieldProps,vars,data);
        //  console.log('fieldProps', str, params, vars, formItemProps);
        return params;
      }
      return fieldProps;
    },[fieldProps])

    return (
      <Field
        key={field}
        field={field}
        valueType={valueType}
        fieldProps={fieldParams}
        form={form}
        preValueChange={preValueChange}
        {...props}
      />
    )
  }

  const rules = useMemo(() => {
    if(formItemProps.validator){
      return [
        ...formItemProps.rules,
        { 
          trigger: formItemProps.validateTrigger,
          validator: async (value, callback) => {
            const formData = form.getFields();
            const result = formItemProps.validator(formData, callback);
            if(isPromise(result)) await result;
          }
        }
      ]
    }
    return formItemProps.rules;
  },[formItemProps.rules])

  const RenderElement = useMemo(() => {
    if(formats && formats[valueType]){
      const FRender: any = formats[valueType];
      // 来自 context 获取到的render 参数
      return <FRender {...fieldProps} />
    }
    return Render? <Render form={form} Field={FieldRender} {...fieldProps} /> : <FieldRender />;
  },[])

  /**
   * 渲染 FormItem
   */
  const getFormItem = () => {
    if(notCol){
      return (
        <Form.Item {...formItemProps} rules={rules} shouldUpdate={undefined} key={field}>
          {RenderElement}
        </Form.Item>
      )
    }else {
      return (
        <Col {...colProps}>
          <Form.Item {...formItemProps} rules={rules} shouldUpdate={undefined} key={field}>
            {RenderElement}
          </Form.Item>
        </Col>
      )
    }
  }

  const children = useMemo(() => {
    /**
     * 判断是否监听了其他依赖性
     */
    if(show !== undefined || formItemProps.shouldUpdate){
      return (
        <Form.Item shouldUpdate={formItemProps.shouldUpdate || true} noStyle>
          {() => {
            const values = form.getFields();
            const data = {
              // 为啥要取pField值，因为对比只会取最外层的数据
              ...(pField? _.get(values, pField) : values),
              formData: oForm.getFields(),
            };
            // console.log(formItemProps.field, pField, values,  data)
            if(show !== undefined){
              if(show && isVerifySync(show, data)){
                return getFormItem();
              }
              return null;
            }else {
              return getFormItem();
            }
          }}
        </Form.Item>
      )
    }

    return getFormItem();
  }, [formItemProps])

  return children;

};

export default FormItemRender;
