import React, { useRef, useCallback, memo, useMemo, useEffect } from 'react';
import CustomView from '../CustomView';
import styles from './index.module.less';
import Store from '../store';
import ContentStore from 'src/components/container/store';
import { useObserver } from 'mobx-react';
import { convertToTree } from 'src/utils';

interface ContentProps {
  list: any[];
  page: any;
  elementProps: any;
}
/**
 * 页面内容区域
 * @param width 1200
 * @param height 800
 */
const CustomContent =  memo(({ list, page, elementProps }: ContentProps) => {
  return useObserver(() => {

    const nodeList = useMemo(() => {
        return convertToTree(list || []);
    },[list])

    const contentData = useMemo(() => new ContentStore({ page }), [])

    const children = useMemo(() => {
        contentData.props = elementProps;
        // console.log("elementProps", list) 
        const getElementList = (list) => {
            if(!list || list.length === 0) return null;
            return list.map((o) => {
            return (
                <CustomView
                    key={o.id}
                    contentData={contentData}
                    item={o} 
                >
                    {getElementList(o.children)}
                </CustomView>
            );
            });
        }
        return getElementList(nodeList);
    }, [list, elementProps]);


    return (
      <React.Fragment>
        {children}
      </React.Fragment>
    );
  });
});



export const createCustomNode = ({ list, page }) => {

    return (props: any) => {
        return <CustomContent list={list} page={page} elementProps={props} />   
    }
}

export default CustomContent;