import { FormProps, TableColumnProps } from "@arco-design/web-react";
import { action, computed, observable, toJS, makeObservable } from "mobx";
import { FormListField } from "src/types/form";
import { formFields } from "src/types/schema";
import _ from 'lodash';
import { addItemByFormList, generateFormListKeys, removeItemByFormList, schemaToFormItem, getRefSchema } from "src/utils/form";
import { FormItem } from "../interface";


class Store {
    rowData = null;
    rowIndex = 0;

    form: FormProps['form'];
    field: string;
    item: any;
    renderFormItemList: any;

    // fields 是根据formlist 集合生产，但实际上和 表格实际Data内容并没有直接关联
    @observable fields = [];
    @action
    setFields = (list) => {
        this.fields = list;
    }

    constructor() {
        makeObservable(this);
    }

    @computed get formList(){
        const { item, field } = this;
        if(item.list.valueType === formFields.refSchema){
            const fieldProps = item.list.fieldProps;
            const [s, paths] = getRefSchema(fieldProps.$ref, fieldProps.schema);
            if(s){
                const objSchema = _.cloneDeep(s);
                objSchema.title = objSchema.title || paths.pop();
                objSchema.definitions = _.cloneDeep(fieldProps.schema.definitions);
                return schemaToFormItem(objSchema, field);
            }

            return [];
        }
        return item.list.children;
    }

    get getItemDefaultValue(){
        return this.formList.reduce((objs, item) => {
            if(item.default !== undefined){
                return {
                    ...objs,
                    [item.field]: item.default
                }
            }
            return objs;
        }, {})
    }

    caches: any = {};
    /**
     * 因为formItem 渲染FormItem资源消耗太多, 使用缓存优化
     */
    getFormItem = (o, key) => {
        if(this.caches[key]) return this.caches[key];
        console.log('getFormItem', o)
        const list: FormItem[] = [{
            ...o,
            formItemProps:{
                // 0907 当前formItemProps 中配置不应该透传
                // ...item.formItemProps,
                noStyle: true,
            },
            notCol: true,
            field: key
        }]
        this.caches[key] = this.renderFormItemList(list);
        return this.caches[key];
    }

    @computed get list(){
        const { formList, renderFormItemList } = this;
        if(!formList.length) return[];

        const result = formList.map((o) => {
            if(o.field === "children") {
                return null;
            };
            return {
                title: o.label || o.field,
                dataIndex: o.field,
                render: (_, record, index) => {
                    return this.getFormItem(o, `${record.field}[${index}].${o.field}`);
                }
            } as TableColumnProps;
        })

        return result.filter((o) => o)
    }

    @observable visible = false;
    @action
    setVisible = (bool) => {
        this.visible = bool;
    }

    init = () => {
        const { form, field } = this;
        const values = form.getFieldValue(field);
        if(Array.isArray(values)){
            // 第一次从表单获取到当前数据结构，根据数据结构生成columns 列表
            const list = generateFormListKeys(values, field);
            this.setFields(list);
        }
    }

    remove = (record: FormListField, index: number) => {
        const { form, fields, setFields } = this;
        const innerSetFieldValue = form.getInnerMethods(true).innerSetFieldValue;
        // 删除field 字段
        const result = removeItemByFormList(fields, record.key);
        setFields(result);
        // 从表单中删除,强制更新对应field
        const field = record.field;
        var value = form.getFieldValue(field) || [];
        var newValue = value.filter(function (_, i) { return i !== index; });
        innerSetFieldValue(field, newValue);
    };

    addItem = (record: FormListField, index: number) => {
        const { form, fields, setFields } = this;
        const innerSetFieldValue = form.getInnerMethods(true).innerSetFieldValue;
        const result = toJS(fields);
        addItemByFormList(result, record.key);
        setFields(result);
        // 从表单中删除对应强制更新对于field
        const field = record.field;
        var value = form.getFieldValue(field) || [];
        value.splice(index + 1, 0, this.getItemDefaultValue);
        innerSetFieldValue(field, value);
    }

    get title(){
        return "RowData";
    }
}

export default Store;