export const getUrlData = (url: string) => {
  const urls = url.split('?');
  const arr = urls[1] ? urls[1].split('&') : [];
  const obj: any = {};
  for (const i of arr) {
    obj[i.split('=')[0]] = i.split('=')[1];
  }
  return { url: urls[0], data: obj };
};


/**
 * 获取schema 设置default 默认值
 * @param json JSONSchema
 * @returns 返回JSONSchema 中default 值
 */
export const schemaToDefault = (json: JSONSchema) => {
  if(!json) return json;
  if('default' in json) return json.default;
  if(json.type === 'object'){
      const properties = json.properties;
      if (properties) {
        let val = {};
        Object.keys(properties).forEach((key) => {
          // 对象深度获取default 值
          const objVal = schemaToDefault(properties[key])
          if(objVal !== undefined){
            val[key] = objVal;
          }
        });
        // 只有有值的时候返回
        if(Object.keys(val).length) return val;
      }
  }
};

/**
 * 5.6 改动，undefined 将不在返回json数据，包括对象和数组
 * @name 解析JSONSchema数据 (将JSONSchema转为JSON数据)
 * @param json  JSONSchema
 * @param data  // jsonSchema 路径变量会根据data值进行替换
 */
export const schemaToJSON = (json: JSONSchema, data?: any, option:{
  // 是否返回空值，undefined值 （默认不返回）
  isNull?: boolean;
} = {}) => {
  if(!json) return json;
  // 新加逻辑，json允许直接输入字符串（此处逻辑，目前用于flow流程节点中，body 参数
  if(typeof json === 'string') return getBuilderValue(json, data);
  const value = json.default;
  let val: any = value;
  switch (json.type) {
    case 'string':
      val = data ? getBuilderValue(value, data) : value;
      break;
    case 'object':
      const properties = json.properties;
      if (properties) {
        val = {};
        Object.keys(properties).forEach((key) => {
          // 5.6，判断对象是否不存在，undefined （不在返回到json中）
          const objVal = schemaToJSON(properties[key], data);
          if(objVal !== undefined || option.isNull){
            val[key] = objVal;
          }
        });
      }
      break;
    case 'array':
      if(value && Array.isArray(value)){
        val = value
      }else if(json.items){
        if(Array.isArray(json.items)){
          val = json.items.map((o) => schemaToJSON(o, data));
        }else {
          // Array<object> 类型，未指定默认值，返回空数组
          val = [];
          // const item = schemaToJSON(json.items as JSONSchema, data);
          // val = item? [item] : [];
        }
      }
      break;
    case 'integer':
    case 'number':
      val = value;
      break;
    case 'null':
      val = null;
    break;
  }
  return val;
};

/**
 * @name 根据新的对象生产 JSON Schema 数据
 * @param val
 * @param json
 */
export const jsonToSchema = (val: any, json: JSONSchema = {}) => {
  
  const obj: JSONSchema = { type: 'object' };
  const valType = typeof val;
  switch (valType) {
    case 'bigint':
      obj.type = 'integer';
      break;
    case 'boolean':
      obj.type = 'boolean';
      break;
    // case 'function':
    case 'number':
      // if (Math.ceil(val) === val) {
      //   obj.type = 'integer';
      // } else {
        obj.type = 'number';
      // }
      break;
    case 'object':
      obj.type = 'object';
      if (!val) {
        obj.type = 'null';
      } else if (Array.isArray(val)) {
        obj.type = 'array';
        const list = val;
        if(list.length){
          const arr = Array.from(
            new Set(
              list.map((o) => {
                // if(typeof o === 'object' ){
                //     return Object.keys(o).join('.')
                // }
                return typeof o;
              })
            )
          );
          if (arr.length === 1) {
            let listItem = list[0];
            // 对象类型，进行参数合并
            if (typeof listItem === 'object' && !Array.isArray(listItem)) {
              listItem = list.reduce(
                (objs, option) => Object.assign(objs, option),
                {}
              );
            }
            obj.items = jsonToSchema(
              listItem,
              Array.isArray(json?.items) ? json?.items[0] : json?.items
            );
            // 判断如果是对象，根据数组值判断数值类型是否为必填项
            if (obj.items.type === 'object') {
              const properties = obj.items.properties as JSONSchema['properties'];
              if (properties) {
                obj.items.required = Object.keys(properties).filter((ik) =>
                  list.every((o) => ik in o)
                );
              }
            }
          } else {
            obj.items = list.map((o, i) =>
              jsonToSchema(
                o,
                Array.isArray(json?.items)
                  ? json?.items[i]
                  : i === 1
                  ? json?.items
                  : undefined
              )
            );
          }
        }else {
          // 如果是空数组，试着从schema 中集成items 数据
          obj.items = json.items;
        }
      } else {
        const properties: JSONSchema['properties'] = {};
        Object.keys(val).forEach((key) => {
          properties[key] = jsonToSchema(
            val[key],
            json?.properties ? json.properties[key] : undefined
          );
        });
        obj.properties = properties;
      }
      break;
    case 'string':
      obj.type = 'string';
      break;
    // case 'symbol':
    case 'undefined':
      obj.type = 'string';
      break;
  }
  if (json?.type === obj.type) {
    _.assign(obj, _.omit(json, ['properties', 'items']));
  }
  if (valType !== 'object' || Array.isArray(val)) {
    obj.default = val;
  }
  return obj;
};

/**
 * @name 根schema 和制定keys 踢出一些属性
 */
export const removeSchemaProperties = (schema: JSONSchema, keys: string[]) => {
  if(schema.type === "object" && schema.properties){
    Object.keys(schema.properties).forEach((key) => {
      schema.properties[key] = removeSchemaProperties(schema.properties[key], keys);
    })
  }else if(schema.type === "array" && schema.items){
    if(Array.isArray(schema.items)){
      schema.items = schema.items.map((o) => removeSchemaProperties(o, keys));
    }else {
      Object.keys(schema.items).forEach((key) => {
        schema.items[key] = removeSchemaProperties(schema.items[key], keys);
      })
    }
  }
  for (const key of keys) {
    delete schema[key];
  }
  return schema;
}

