/**
 * 创建事件系统
 * @param store 页面store
 * @returns 
 */
export const createEvent = (store: Store) => {

    const getFun = (config: functionConfig) => {

        console.log('createEvent', config)
        switch(config.type){
            case functionTypes.page:
                return createPageEvent(config);
            
        }

        return () => {
            alert("createEvent")
        };
    }

    return (config) => {
        const { all } = config;
        // 创建子事件，如果存在
        const allEvent = (all || []).map((o) => getFun(o));
        const mainEvent = getFun(config); // 创建主事件
        
        console.log('mainEvent', mainEvent)
        return async () => {
            const result = mainEvent()
            for (const fun of allEvent) {
                await fun();
            }
            return result;
        }
    };
}







/**
 * 创建数据源系统
 */
export const fetchData = () => {
    const objs = {};
    const update = action((key, values) => {
        objs[key].set(values);
        // 数据更新成功
        console.log('update', objs[key], values);
    })

    return (config: fetchDataConfig) => {
        const key = Object.assign(config);

        if(!objs[key]){
            objs[key] = observable.box([]);
            setTimeout(() => {
                update(key, [
                    { label: "1111", value: 111 }
                ])
            },1000)
        }
        console.log("fetchData", "数据源加载成功", key, objs[key].get());

        return toJS(objs[key].get());
    }
}












/**
 * 创建校验器
 */
export const createValidate = (store: Store) => {

    return (config: validateConfig[]) => {

        return config.some((rule) => isVerify(rule, store))
    }
}