import { DatasetProps } from "src/types/parse";

// 允许定义的变量
const names = {
    v: true,
    u: true,
    vm: true,
}


export const camelToKebab = (str) => {
    return str.replace(/[A-Z]/g, match => `-${match.toLowerCase()}`);
}


/**
 * 获取datset 数据
 */
export const getDataSet = (html: HTMLElement): DatasetProps => {
    const dataset = html.dataset;

    return Object.keys(dataset).reduce((obj, str) => {
        const [name, value] = camelToKebab(str).split('-');
        if(names[name] && value){
            obj[name] = value;
        }
        return obj;
    },{ ...dataset }) as any
}


/**
 * 对props 参数进行解析，实现文本到路径的替换
 * 例如 { name: 1, s: { ss: "2342" } } => { 1: ['name'],  2342: ["s", "ss"] }
 */
export const nonSwapObject = (data: any) => {
    const setObj = {}; // 记录每个文本的set Obj 值
    function swapObject(obj, path = []) {
        const result = {};
      
        for (const key in obj) {
          const value = obj[key];
          const newPath = [...path, key];
      
          if (typeof value === 'object' && value !== null) {
            // 递归处理嵌套对象
            const nestedResult = swapObject(value, newPath);
            for (const nestedKey in nestedResult) {
                result[nestedKey] = nestedResult[nestedKey]; // 使用 concat 避免重复添加嵌套键
                setObj[nestedKey] = (setObj[nestedKey] || 0) + 1;
              }
          } else {
            // 处理基本类型值
            result[value] = newPath;
            setObj[value] = (setObj[value] || 0) + 1;
          }
        }
      
        return result;
    }
    const objData = swapObject(data);
    for (const key in setObj) {
        if(setObj[key] > 1) {
            // 去除重复出现过的key
            delete objData[key]
        }
    }
    return objData;
}
  