import React, { useRef, useCallback, memo, useMemo, HTMLProps, useState, useEffect } from 'react';
import { useDrop } from 'react-dnd';
import classnames from 'classnames';
import Store from '../../store';
import config from "src/config";
import { ListItem, ModuleItem } from '../../interface';
import { NodeElementContext } from '../../NodeElement/context';
import './index.less';

/**
 * @name 拖动添加占位符元素
 */
interface PlaceholderProps {
  isInline?: boolean;
  style?: React.CSSProperties;
}
export const Placeholder = (props?: PlaceholderProps) => {
  const { isInline, style } = props || {};
  const styleProps = useMemo(() => {
    if(isInline) return { display: 'inline-block', ...style };
    return style;
  },[])
  return (
    <div
      className={'drop-page-placeholder'}
      style={styleProps}
    >
      +
    </div>
  );
};

interface DropViewProps extends HTMLProps<HTMLDivElement> {
  loading?: boolean;
  // 是否可编辑
  notEdit?: boolean;
  children?: any;
  store: Store;
}

export default ({ loading, store, notEdit, children, ...props }: DropViewProps) => {
  const ref = useRef(null);
  const contextValue = useMemo(() => ({ store }), []);
  const [[isOver, oItem], drop] = useDrop({
    accept: store.type,
    hover: (item, monitor) => {
      // console.log('hover', item)
      // if(!containerBool || !dropBool){
      //     updateContainer();
      // }
    },
    drop: (item: ListItem | ModuleItem, monitor) => {
      // console.log('drop', item, monitor.didDrop())
      if (monitor.didDrop()) return;
      // 当前拖动组件如果存在id，则更新排序
      if ('id' in item) {
        store.updateList(item);
      } else {
        store.addList(item as ModuleItem);
      }
      // if(dropBool && containerBool){
      //     addModule(item);
      // }
    },
    collect: (monitor) => {
      // 当前容器是否接收到元素
      // updateDidDrop(monitor.isOver());
      // if(!dropBool) return {};
      return [monitor.isOver({ shallow: true }), monitor.getItem()];
    },
  });

  drop(ref);

  if(store.page.contexts && store.page.contexts.length){
    for (const item of store.page.contexts) {
      store.contentData[item.name] = config.run.state.contexts[item.context];
      store.contentData._arguments[item.name] = store.contentData[item.name];
    }
  }

  // useEffect(( ) => {
  //   const dom = ref.current;
  //   dom.addEventListener('mouseover', function(event) {
  //     const hoveredElement: any = event.target;
  //     store.parse.mouseHtml(hoveredElement);
  //     // 处理鼠标停留的元素
  //     // console.log('Mouse over element:', hoveredElement);
  //   });
    
  //   dom.addEventListener('mouseout', function(event) {
  //     const html: any = event.target;
  //     store.parse.mouseoutHtml(html);
  //   })
  //   // document.addEventListener('mouseover', function(event) {
  //   //     const hoveredElement = event.target;
  //   //     // 处理鼠标停留的元素
  //   //     console.log('Mouse over element:', hoveredElement.innerHTML);
  //   // });
  // },[])


  return (
    <div
      ref={ref}
      {...props}
      className={classnames({
        ['drop-page-content']: true,
        // [styles['drop-page-content-taro']]: store.platform === modulePlatform.taro,
        ['drop-page-hover']: isOver,
        ['drop-page-not-image']: notEdit,
      }, props.className)}
    >
      <NodeElementContext.Provider value={contextValue}>
        {children}
      </NodeElementContext.Provider>
      {isOver && <Placeholder {...oItem} />}
    </div>
  );
};
