import Store from 'src/components/container/store';
import { getBuilderItems } from "./builder";
import _, { get as safeGet, set as safeSet } from 'lodash';
import envConfig from 'src/config';
import { tsTojsString } from './js';
import config from 'src/config';

// 输入验证和过滤
export function sanitizeInput(input) {
    // 验证输入是否存在并是字符串类型
    if (typeof input !== 'string') {
      throw new Error('Invalid input');
    }
  
    // 去除首尾的空格
    const trimmedInput = input.trim();
  
    // 使用正则表达式过滤非法字符
    const filteredInput = trimmedInput.replace(/[^a-zA-Z0-9-_]/g, '');
  
    console.log('filteredInput', filteredInput)
    // 检查是否包含非法的 AJAX 关键字
    if (filteredInput.includes('ajax') || filteredInput.includes('XMLHttpRequest')) {
      throw new Error('AJAX usage not allowed');
    }
  
    // 返回经过验证和过滤的输入
    return filteredInput;
}

