/**
 * 创建function 函数
 */
export function executeSandboxedCode(funStr, store: Store) {

  try{
    // 如果使用了for 函数，可能会添加其他属性
    const fun = (new Function(
      `store, globals`,
      `
        const { ${Object.keys(config.run).join(',')} } = globals;
        const props = {}
        const { ${Object.keys(_.omit(store, ['_arguments'])).join(',')} } = store;
        return ${tsTojsString(funStr)}
      `
    ))
    return fun(store, config.run);
  }catch{
  }

  return undefined;
  
}


/**
 * 创建变量执行函数
 */
export function executeJsCode(funStr, store: Store){
  try{
    const keys = Object.keys(envConfig.run);
    return (new Function(
      `{${keys.join(',')}}, store`,
      `
        const props = {};
        const { ${store._custom_prototype.getPageFunctionToArguments()} } = store;
        return (${funStr});
      `
    ))(envConfig.run, store)
  }catch(e){
    console.error('executeJsCodeError：', e, funStr)
  }

  return undefined;
}


/**
 * @name 遍历对象，根据构造器转换为js可识别数据
 * @param data {}
 */
export function getBuilderToJsCode(data: any){
  if(!data) return data;
  const list = getBuilderItems(data);
  for (const item of list) {
    const { key, path, pathStr } = item;
    const value = safeGet(data, key, '');
    const pathParam = JSON.stringify(path).replace(/"/g,"'");
    if(value === pathStr){
      safeSet(data, key, `this.data[${pathParam}]`);
    }else {
      safeSet(data, key, value.replace(pathStr, `\${this.data[${pathParam}]}`));
    }
  }
  return data;
 }
  
