import { Button, ButtonProps, Divider, Form, Message, Modal, Radio, Space, Typography } from "@arco-design/web-react";
import { useContext, useEffect, useMemo, useState } from "react";
import type { pageDataProps } from "src/components/CustomPage/interface";
import type, { FormGeneragteProps } from "src/components/FormGenerate";
import FormGeneragteContext from "src/components/FormGenerate/context";
import type { JSONSchemaCustom } from 'src/components/schema/interface';
import SchemaForm from "src/components/schema/Form";
import _ from 'lodash';
import { isBuilder, isBuilderFun } from "src/utils/is";

// export interface EditReactNodeProps extends Omit<CustomPageProps, 'store'> {
interface BaseProps {
    list?: JSONSchema[];
    value?: pageDataProps['list'] ;
    onChange?: (val: pageDataProps['list']) => void;
}

export type EditUnionProps = BaseProps & {
    isComponent?: boolean;
    widgets?: FormGeneragteProps['widgets']
    value?: any;
    buttonProps?: ButtonProps;
    onChange?: (val: any) => void;
}

/**
 * @name 组合类型编辑器
 * 总共类型 function string number boolean object array
 */
function EditUnion({ widgets, list, buttonProps, value, onChange, ...props }: EditUnionProps){

    // const [visible, setVisible] = useState<boolean>(false);
    // const [radio, setRadio] = useState<string>();
    
    const [form] = Form.useForm();
    const schema = useMemo(() => {
        const objs: JSONSchemaCustom = { 
            type: "object",
            properties: {
                radio: { type: "string", format: "radio", formItemProps: { noStyle: true } },
            } 
        };
        const types: any = {};
        if(Array.isArray(list)){
            // console.log('list', list);
            for (const o of list) {
                _.set(o, ['fieldProps'], props);
                o.formItemProps = { noStyle: true };
                if(["function", "node"].includes(o.format)) {
                    if(!types[o.format]) {
                        types[o.format] = true;
                        objs.properties[o.format] = {
                            ...o,
                            show: {
                                radio: o.format,
                            },
                            formItemProps: { ...o.formItemProps, noStyle: true, shouldUpdate: ['radio'] }
                        };
                    }
                } else if(!Array.isArray(o.type)){
                    const type = o.type || "string";
                    if(!types[type]){
                        types[type] = true;
                        objs.properties[type] = {
                            type,
                            show: {
                                radio: type,
                            },
                            ...o,
                            formItemProps: { ...o.formItemProps, noStyle: true, shouldUpdate: ['radio'] }
                        };
                    }
                }
            }
        }
        objs.properties.radio.enum = Object.keys(types);
        // return schemaToFormItem(objs);
        return objs;
    },[list])
    useEffect(() => {
        const values: any = {};
        switch(typeof value){
            case 'object':
                if(value && schema.properties.node){
                    values.radio = "node";
                }else if(Array.isArray(value)){
                    values.radio = "array";
                }else {
                    values.radio = "object";
                }
            break;
            case 'string':
                if(isBuilderFun(value)){
                    values.radio = "function";
                }else {
                    values.radio = "string";
                }
            break;
            case 'boolean':
            case 'number':
                values.radio = typeof value;
            break;
            case 'bigint':
                values.radio = "number";
            break;
        }
        if(values.radio && schema.properties[values.radio]){
            values[values.radio] = value;
            form.setFieldsValue(values);
        }else {
            const keys = Object.keys(schema.properties);
            if(keys[1]){
                form.setFieldsValue({ radio: keys[1] });
            }
        }
    },[value, schema])
 

    return (
        <FormGeneragteContext.Provider value={{}}>
            <SchemaForm
                schema={schema}
                form={form}
                layout="vertical"
                generagteProps={{
                    cols: 24
                }}
                onValuesChange={(data, { radio, ...vals }) => {
                    const keys = Object.keys(data);
                    if(keys[0] !== "radio"){
                        if(onChange) onChange(data[keys[0]])
                    }
                }}
            />
        </FormGeneragteContext.Provider>
    )
}

export default EditUnion;