import MyErrorBoundary from 'src/components/custom/MyErrorBoundary';
import { executeJsCode, executeSandboxedCode } from 'src/utils/function';

interface ContentProps {
  store: Store;
  page?: pageDataProps['page'];
  list: pageDataProps['list'];
}

const basics = {
  basics_for: (fun: any, children: any[], props: ForProps, store: Store) => {
    const { each, of, index, varName, varBody } = props;
    if(!Array.isArray(of)){
      return null;
    }
    return of.map((item, i) => {
      const contentData: Store = Object.create(store);
      contentData._arguments = {
          ...contentData._arguments,
          [each || "item"]: item,
          [index || "index"]: i
      }
      if(varName && varBody){
        contentData._arguments[varName] = executeJsCode(varBody, contentData);
      }
      Object.assign(contentData, contentData._arguments);
      // console.log('contentData', store, contentData)
      
      return fun(children, contentData);
    })
  },
  basics_text: (fun: any, children: any[], props: any, store: Store) => {
    return props.value || null
  }
}

interface ElementUIProps {
  o: any;
  contentData: Store;
  getElementList: (a,b) => any[] | null;
}
const ElementUI = ({ o, contentData, getElementList }: ElementUIProps) => {
  // console.log(o.key, o.props);
  // const Element = useMemo(() => {
  //   return moduleStore.elements.get(o.key).render;
  // },[])
  // const vars = getBuilderItems(o.props, o.key);

  const Element  = moduleStore.elements.get(o.key).render;
  if(o.props.ref){
    // 如果用户绑定了 ref，则更改为全局绑定
    contentData.$refs[o.props.ref] = useRef();
  }
  // const vModel: string = o.props["v-model"];

  // console.log('vModel', vModel);
  return useObserver(() => {
    const [vars] = useState<builderItem[]>(() => getBuilderItems(o.props, o.key))
    // 动态监听props
    const props = useMemo(() => {
      // let props =  JSON.parse(JSON.stringify(o.props))
      let props = cloneDeep(o.props);
      if(vars.length){
        props = getDataBuilder(props, vars, contentData);
      }
      if(props.ref){
        props.ref = contentData.$refs[props.ref];
      }
      props = moduleStore.getModuleProps(o.key, props, contentData);
      // if(vModel){
      //   // 双向绑定数据处理
      //   props.value = safeGet(contentData.data, vModel);
      //   const onChange = props.onChange;
      //   props.onChange = (val, ...args) => {
      //     const [key, ...keys] = vModel.split('.');
      //     if(keys.length){
      //       // 如果绑定的是多级对象，因为已经对mobx进行了转化，所以更新无法触发mobx刷新，所以要更新根对象
      //       const value = contentData.data[key];
      //       safeSet(value, keys, val);
      //       contentData.data[key] = value;
      //     }else {
      //       contentData.data[key] = val;
      //     }
      //     if(onChange && typeof onChange === "function"){
      //       // 如果监听了onChange 事件，依然可以继续监听
      //       onChange.apply(contentData, [val, ...args]);
      //     }
      //   }
      // }
      return props;
    },[o.props])
    // console.log(o.key, vars, props, o, contentData);

    // console.log("childrenRender", o, getElementList(o.children, contentData));
    
    let children = getElementList(o.children, contentData);
    if(typeof props.children !== "undefined"){
      // 系统中存在两种 children类型，一种在props 中作为参数进行传输，还有一个是children 是通过拖拽子类添加
      // 第一种目前针对的一半是 string 类型参数
      // 两种children 合并展示，否则在input 中返回多个 null 则会报错
      if(children) children.push(props.children);
      else children = props.children;
    }
    if(children && children.length === 1){
      // 例如 Tooltip组件，这种不支持ReactNode[] 所以单个组件不能使用数组进行添加
      children = children[0]
    }
    return (
      <Element key={o.id} data-id={o.id} {...props}>
        {children}
      </Element>
    );
  })
}

/**
 * 页面内容区域 web-container
 * @param width 750
 * @param height 900
 */
function Content({ store, list, page = {} }: ContentProps){

  useState(() => {
    if(page.created){
      const fun = executeSandboxedCode(page.created, store);
      if(fun) fun()
    }
  })

  useEffect(() => {
    if(page.mounted){
      const fun = executeSandboxedCode(page.mounted, store);
      if(fun) fun()
    }
    return () => {
      if(page.beforeUnmount){
        const fun = executeSandboxedCode(page.beforeUnmount, store);
        if(fun) fun()
      }
    }
  },[])

  const children = useMemo(() => {
    const getElementList = (list, contentData: Store) => {
      if(!Array.isArray(list) || list.length === 0) return null;
      return list.map((o: any, i) => {
        if(basics[o.key]){
          const vars = getBuilderItems(o.props, o.key);
          const props = getDataBuilder(o.props, vars, contentData);
          // 控制器类型
          return basics[o.key](getElementList, o.children, props, contentData);
        }
        // return ElementUI({ 
        //   o,
        //   contentData,
        //   getElementList,
        // })
        return <ElementUI key={i} o={o} contentData={contentData} getElementList={getElementList} />
      });
    }
    return getElementList(list, store);
  }, [list]);

  return (
    <MyErrorBoundary>
      {children}
    </MyErrorBoundary>
  );
};

export default Content;