import React from 'react';
import { ListItem, ModuleItem } from "src/components/CustomPage/interface";
import { ElementItem, SpecialItem } from "src/types/module";
import { JSONSchemaItemProps } from "src/types/schema";
import { mergeSchemasRefs, schemaToList } from "./schema";
import NodeElement from 'src/components/container/NodeElement';
import { treeToFlatten } from '.';
import config from "src/config";
import _, { result } from 'lodash';
export const moduleFormats = ['icon', 'js', 'function', 'functionNode', 'node']


export const getModuleItem = (item: ModuleItem) => {
    const { id, props, extraInfo, content, ...data }: any = item;
    return {
      props: JSON.parse(props || '{}'),
      extraInfo: JSON.parse(extraInfo || '{}'),
      content: JSON.parse(content || '{}'),
      key: id.toString(),
      ...data
    }
}

/**
 * @name 获取schema 中置顶format 特殊类型路径
 * @returns
 */
export function schemaFormatSpecialPath(jsonSchema: JSONSchema){
    // console.log('schemaToList', schemaToList, jsonSchema)

    const schema = mergeSchemasRefs(jsonSchema);
    const list = schemaToList(schema, []).children;
    if(!Array.isArray(list)) return [];
    let result = [];
    function recursionList(item: JSONSchemaItemProps, obj: SpecialItem, parentPaths: string[] = []) {
        const schema = item._store;
        if (item.children && item.children.length > 0) {
            if(schema.items && !Array.isArray(schema.items)){
                // 处理 items 是数组的情况
                let child = [];
                item.children.forEach((o) => {
                    let childObj: SpecialItem = {
                        paths: []
                    }
                    const list = recursionList(o, childObj, [...item.path, '0']);
                    if(Array.isArray(list) && list.length){
                        child = child.concat(list);
                    }
                    if(childObj.paths && childObj.paths.length){
                        child.push(childObj);
                    }
                });
                if(child.length){
                    obj.paths = item.path.slice(parentPaths.length);
                    obj.child = child;
                }
            }else {
                let child = [];
                const list = item.children.map((o) => {
                    // [ a: { b: 1, c: 2 }] 按照 [a,b] [a,c] 层级进行处理
                    let itemObj: SpecialItem = {
                        paths: [],
                    };
                    // { a.b.c.d } 形式
                    const list = recursionList(o, itemObj, parentPaths);
                    if(Array.isArray(list) && list.length){
                        child = child.concat(list);
                    }
                    if(itemObj.paths && itemObj.paths.length){
                        return itemObj;
                    }
                    return null;
                }).filter((o) => o);
                return child.concat(list);
            }
        }else {
            if(schema.anyOf){
                let child = [];
                item.anyOf.forEach((o) => {
                    // 对于组合类型进行筛选
                    let obj: SpecialItem = {
                        paths: [],
                    };
                    const list = recursionList(o, obj, parentPaths);
                    if(Array.isArray(list) && list.length){
                        child = child.concat(list);
                    }
                    if(obj.paths && obj.paths.length){
                        child.push(obj);
                    }
                })
                return child;
            }else {
                if(schema.format){
                    if(config.schema.sources[schema.format] || moduleFormats.includes(schema.format)){
                        // 针对schema 类型做特殊处理
                        obj.paths = item.path.slice(parentPaths.length);
                        obj.format = schema.format;
                        if(schema.functionType){
                            _.set(obj, ['params', 'functionType'], schema.functionType);
                        }
                    }
                }else if(schema.type == "boolean"){
                    // boolean 类型做特殊处理（创建校验器）
                    obj.paths = item.path.slice(parentPaths.length);
                    obj.format = "switch";
                }
            }
        }
    }
      
    list.forEach((item) => {
        if(item.anyOf){
            item.anyOf.forEach((o) => {
                // 对于组合类型进行筛选
                let obj: SpecialItem = {
                    paths: [],
                };
                const list = recursionList(o, obj);
                if(Array.isArray(list) && list.length){
                    result = result.concat(list);
                }
                if(obj.paths && obj.paths.length){
                    result.push(obj);
                }
            })
        }else {
            let obj: SpecialItem = {
                paths: [],
            };
            const list = recursionList(item, obj);
            if(Array.isArray(list) && list.length){
                result = result.concat(list);
            }
            if(obj.paths && obj.paths.length){
                result.push(obj);
            }
        }
    });
    // console.log('schemaToList', result, schemaToList, jsonSchema)
    return result;
}

/**
 * @name 将大写字符转换为小写并在前面添加下划线
 * 'SomeUppercaseChar'; => 输出: some_uppercase_char
 */
export function convertToSnakeCase(str) {
    const convertedStr = str.replace(/[A-Z]/g, match => '_' + match.toLowerCase());
    
    // 如果第一个字符是下划线，则去除它
    if (convertedStr.charAt(0) === '_') {
      return convertedStr.slice(1);
    }
    
    return convertedStr.replace('.', '');
}


/**
 * 创建新的react 自定义组件渲染
 */
export function createNodeElement(data: ElementItem[]): any{
    const list = treeToFlatten(data);
    return React.createElement(NodeElement, {
        list,
        store: this,
        key: Date.now(),
    })
}