import { Form, FormProps, Collapse, CollapseProps, CollapseItemProps, Modal, ModalProps } from "@arco-design/web-react"
import FormGeneragte, { FormGeneragteProps } from "src/components/FormGenerate";
import React, { ReactNode, useEffect, useMemo, useState } from "react";
import { schemaToFormItem } from "src/utils/form";
import { JSONSchemaCustom } from "src/components/schema/interface";
import { isPromise } from "src/utils/is";

/**
 * @name 解析JSONSchema数据 (将JSONSchema转为JSON数据)
 * @param json  JSONSchema
 * @param data  // jsonSchema 路径变量会根据data值进行替换
 */
const schemaToJSON = (json: JSONSchema, data?: any, option:{
    // 是否返回空值，undefined值 （默认不返回）
    isNull?: boolean;
  } = {}) => {
    if(!json) return json;
    // 新加逻辑，json允许直接输入字符串（此处逻辑，目前用于flow流程节点中，body 参数
    if(typeof json === 'string') return json;
    const value = json.default;
    let val: any = value;
    switch (json.type) {
      case 'string':
        val = value;
        break;
      case 'object':
        const properties = json.properties;
        if (properties) {
          val = {};
          Object.keys(properties).forEach((key) => {
            // 5.6，判断对象是否不存在，undefined （不在返回到json中）
            const objVal = schemaToJSON(properties[key], data);
            if(objVal !== undefined || option.isNull){
              val[key] = objVal;
            }
          });
        }
        break;
      case 'array':
        if(value && Array.isArray(value)){
          val = value
        }else if(json.items){
          if(Array.isArray(json.items)){
            val = json.items.map((o) => schemaToJSON(o, data));
          }else {
            val = [];
          }
        }
        break;
      case 'integer':
      case 'number':
        val = value;
        break;
      case 'null':
        val = null;
      break;
    }
    return val;
  };
  

export interface SchemaFormProps extends FormProps {
    schema: JSONSchemaCustom;
    generagteProps?: Partial<FormGeneragteProps>;
    /**
     * 需要过滤展示的schema 数据
     */
    filterKeys?: string[];
    collapseProps?: CollapseProps;
    collapses?: {
        keys: string[],
        itemProps: CollapseItemProps
    }[]
}
function SchemaForm ({
    form: parentForm,
    schema,
    generagteProps,
    collapses,
    collapseProps,
    filterKeys,
    ...props
}: SchemaFormProps){

    const [form] = parentForm? [parentForm] : Form.useForm();

    const formList = useMemo(() => {
        const defaultValue = schemaToJSON(schema);
        form.setFieldsValue(defaultValue);
        if(!Array.isArray(schema)){
            return schemaToFormItem(schema)
        }
        return [];
    },[schema])

    const formGenerateProps = useMemo(() => {
        if(schema && schema.formGenerateProps){
            return { 
                ...schema.formGenerateProps,
                ...generagteProps
            }
        }
        return generagteProps;
    },[generagteProps, schema])

    const generagte = useMemo(() => {
        if(collapses){
            const collapseRender = collapses.map((o, i) => {
                return (
                    <Collapse.Item key={i} {...o.itemProps}>
                        <FormGeneragte
                            form={form}
                            cols={8}
                            formItemList={formList.filter((item) => o.keys.includes(item.field))}
                            {...formGenerateProps}
                        />
                    </Collapse.Item>
                )
            })
            return (
                <Collapse {...collapseProps}>
                    {collapseRender}
                </Collapse>
            )
        }else {

            if(filterKeys){
                const map =  new Map(formList.map((o) => [o.field, o]));
                const formItemList = filterKeys.map((k) => map.get(k)).filter((o) => Boolean(o));
                return (
                    <FormGeneragte
                        form={form}
                        cols={8}
                        formItemList={formItemList}
                        {...formGenerateProps}
                    />
                )
            }

            return (
                <FormGeneragte
                    form={form}
                    cols={8}
                    formItemList={formList}
                    {...formGenerateProps}
                />
            )
        }
    },[formList, JSON.stringify(filterKeys)])

    return (
        <Form
            form={form}
            {...props}
        >
            {generagte}
        </Form>
    )
}

export interface SchemaFormModalProps extends SchemaFormProps {
    trigger?: ReactNode;
    modalProps?: ModalProps;
    onSuccess?: ModalProps['onOk'];
}
SchemaForm.Modal = ({ trigger, onSuccess, modalProps, ...props }: SchemaFormModalProps) => {

    const [visible, setVisible] = useState<boolean>(false);
    const [form] = props.form? [props.form] : Form.useForm();

    useEffect(() => {
        if(!visible){
            form.clearFields();
        }
    },[visible])

    if(!props.schema) return null;
    return (
        <React.Fragment>
            {trigger && React.cloneElement(trigger as any, {
                onClick: () => {
                    setVisible(true);
                }
            })}
            <Modal
                visible={visible}
                title={props.schema.title}
                onCancel={() => {
                    setVisible(false);
                }}
                escToExit
                unmountOnExit
                onOk={() => {
                    if(onSuccess){
                        return form.validate().then((res) => {
                            const result = onSuccess(res) as Promise<any>;
                            if(isPromise(result)){
                                return result.then((res) => {
                                    setVisible(false);
                                }).finally(() => {
                                    if(props.onSubmit){
                                        props.onSubmit(res);
                                    }
                                })
                            }else {
                                setVisible(false)
                                if(props.onSubmit){
                                    props.onSubmit(res);
                                }
                            }
                        })
                        
                    }
                }}
                {...modalProps}
            >
                <SchemaForm 
                    {...props}
                    form={form}
                />
            </Modal>
        </React.Fragment>
    )
}

export default SchemaForm;