import { isRefSchema } from './is';
import { FormListField } from 'src/types/form';
import config from 'src/config';
import { Pattern } from 'src/types/pattern';

const getOptions = (enumList: JSONSchema['enum']) => {
  return enumList.map((o) => {
    if(typeof o === 'object') return o;
    return { value: o, label: o }
  })
}

const getShouldUpdate = (value: any) => {
  if(Array.isArray(value)){
    return (prev, record) => {
      return value.some((k) => prev[k] !== record[k]);
    }
  }else {
    if(typeof value === "object"){
      const keys = Object.keys(value);
      return (prev, record) => {
        return keys.some((k) => prev[k] !== record[k]);
      }
    }
    return value;
  }
}

/**
 * @name 根据JSONSchema转换为form表单集合
 * @param schema
 * @param field 当前field 参数
 */
export const schemaToFormItem = (originSchema: JSONSchema, field: string = "formData"): FormItem[] => {
  const jsonSchema = _.cloneDeep(toJS(originSchema));
  const getFormItem = (schema: JSONSchema) => {
    if(!schema || !schema.type) return [];
    const properties = schema?.properties;
    const getSchemaItem = (option, key) => {
      const { 
        type = 'string', title, format, pattern, 
        enum: enumList, description, widget,
        dependencies, $ref,
        extraInfo = {},
        listType, functionType,
        colProps, show, anyOf,
        ...props
      } = option;
      const { jsDocs } = extraInfo;
      let extra = description;
      if(!extra && jsDocs){
        for (const item of jsDocs) {
          if(item.comment) extra = item.comment;
          if(item.tags && item.tags.zh) extra = item.tags.zh;
        }
      }
      let item: FormItem = {
        ...props,
        field: key,
        label: title || key,
        listType,
        valueType: formFields.input,
        formItemProps: {
          extra,
          ...option.formItemProps,
          shouldUpdate: getShouldUpdate(option.formItemProps?.shouldUpdate)
        },
        show,
        colProps,
        widget,
        rules: [],
        fieldProps: { ...option.fieldProps },
        formGenerateProps: option.formGenerateProps
      };
      // 判断当前表单是否为必填
      if (schema.required && schema.required.includes(key)) {
        item.rules.push({ required: true, message: `${item.label}不能为空` })
      }
      if(pattern){
        item.rules.push({ match: new RegExp(pattern), message: `${item.label}格式校验失败` })
      }
      if(anyOf && Array.isArray(anyOf)){
        // 多个类型
        item = _.assign(item, {
          valueType: formFields.union,
          fieldProps: {
            list: anyOf,
            ...item.fieldProps,
          }
        } as FormItem)
        return item;
      }
      if(format){
        // config.schema.formats[format]
        switch(format){
          case 'radio':
          case 'radioButton':
          case "select":
            if(enumList){
              item.fieldProps = {
                options: enumList.map((o) => {
                  if(typeof o === 'object') return o;
                  return { value: o, label: o }
                }),
                ...item.fieldProps
              } as any
            }
        }
        if(functionType){
          _.set(item, ['fieldProps', 'functionType'], functionType);
        }
        if(['phone', 'email'].includes(format)){
          // 这边代表正则类型
          item.rules.push({ match: new RegExp(Pattern[format]), message: `${item.label}格式校验失败` })
        }else {
          item.valueType = format as any;
        }
        return item;
      } else if($ref){
        //  "#/definitions/simpleTypes
        if(isRefSchema($ref, jsonSchema)){
          item = _.assign(item, {
            valueType: formFields.refSchema,
            fieldProps: {
              $ref,
              schema: jsonSchema,
              ...item.fieldProps
            }
          })
          return item;
        }
        return;
      } else {
        // 判断类型，根据类型指定参数值
        switch (type) {
          case 'array':
            // item = _.assign(item, { valueType: 'EditorTable' }) as FormItem;
            if (option.items && !Array.isArray(option.items)) {
              if(!option.items.formGenerateProps){
                option.items.formGenerateProps = {
                  cols: 8,
                };
              }
              item.list = getSchemaItem(option.items, key);
              if(item.list && (item.list.children || item.listType === "Table")){
                // 对象和TableEdit默认使用 model 弹窗
                if(!item.formGenerateProps){
                  item.formGenerateProps = {
                    to: "Modal",
                    cols: 24,
                    modalProps: {
                      style: { width: 1000 }
                    }
                  }
                }
              }
              // console.log('item.list', item.label, item.list);
              return item;
            }else {
              if(enumList && Array.isArray(enumList)){
                item = _.assign(item, {
                  valueType: formFields.select,
                  fieldProps: {
                    mode: "multiple",
                    options: getOptions(enumList),
                    ...item.fieldProps,
                  }
                } as unknown as FormItem);
                return item;
              }
              // item 不同规则数组忽略（未开发）
              return;
            }
            break;
          case 'object':
            // 默认使用 model 弹窗
            if(!item.formGenerateProps){
              item.formGenerateProps = {
                to: "Modal",
                cols: 8,
                modalProps: {
                  style: { width: 1000 }
                }
              }
            }
            item.children = getFormItem(option)
            if(!item.children.length) return;
            break;
          case 'string':
            if(format){
              // 定义了特殊类型，需要特别处理的特殊类型
              switch(format){
                case 'dateTime':
                  item =  _.assign(item, {
                    valueType: formFields.date, 
                    fieldProps: { showTime: true, ...option.fieldProps } 
                  } as FormItem);
                break;
                // email, ip, url
                case 'email':
                case 'ip':
                case 'url':
                  item.rules.push({
                    type: format,
                    validateLevel: 'warning',
                  })
                break;
              }
            }
            break;
          case 'integer':
            item = _.assign(item, { valueType: formFields.inputNumber }) as FormItem;
            item.fieldProps = { precision: 0, ...item.fieldProps };
            break;
          case 'number':
            item = _.assign(item, { valueType: formFields.inputNumber });
            break;
          case 'boolean':
            item = _.assign(item, { valueType: formFields.switch });
            break;
        }
      }
      if(enumList && Array.isArray(enumList)){
        item = _.assign(item, {
          valueType: formFields.select,
          fieldProps: {
            options: getOptions(enumList),
            ...item.fieldProps,
          }
        } as FormItem);
      }
    
      return item;
    }
    if (!properties || typeof properties !== 'object') {
      return schema.type == "object"? [] : [getSchemaItem(schema, field)];
    }
    const keys = Object.keys(properties);

    return keys.map((key) => {
      return getSchemaItem(properties[key], key);
    }).filter((item, i) => {
      return item;
    });
  }


  return getFormItem(jsonSchema);

};


/**
 * @name 输出所有字符集合可能
 * @param characters 字符集合 [a , b , c]
 * @param separator 分隔符，默认 '.'
 * @returns [a , b] => [a, b, a.b]
 */
export function generateCombinations(characters: string[], separator = ".") {
  const results = [];
  const n = characters.length;

  // 生成所有可能的组合
  for (let i = 1; i < Math.pow(2, n); i++) {
    const combination = [];
    for (let j = 0; j < n; j++) {
      if ((i >> j) & 1) {
        combination.push(characters[j]);
      }
    }
    results.push(combination.join(separator));
  }

  return results;
}



/**
 * @name 根据table schema 生成适用查询的schema
 * @param schema 
 * @returns schema
 */
export const tableSchemaToSearchSchema = (schema: JSONSchema) => {
  if(!schema && !schema.properties) return schema;

  const objs: JSONSchema = { type: "object", properties: {} };
  const keys = Object.keys(schema.properties);
  for (const key of keys) {
    const item = schema.properties[key];
    const obj: JSONSchema = { ...item };
    const { format } = item;
    
    switch(format){
      case 'date':
        obj.type = "array";
        obj.format = "dateRange";
      break;
      case 'dateTime':
        obj.type = "array";
        obj.format = 'dateRange';
        obj.fieldProps = { ...item.fieldProps, showTime: true };
      break;
      case 'time':
        obj.type = "array";
        obj.format = 'time';
        obj.fieldProps = { ...item.fieldProps, showTime: true };
      break;
      default: 
        if(item.type == 'array' && item.enum){
          let enumKeys = item.enum;
          if(typeof item.enum[0]  === 'object'){
            enumKeys = item.enum.map((o) => o.value);
          }
          obj.enum = enumKeys;
        }
    }

    objs.properties[key] = obj;
  }

  
  return objs;
}

export const schemaToQueryParams = (schema: JSONSchema, param: any) => {
  if(!schema && !schema.properties) return schema;

  const keys = Object.keys(schema.properties);
  for (const key of keys) {
    const { format, type, enum: enumList } = schema.properties[key];
    if(param[key]){
      switch(format){
        case 'date':
        case 'time':
        case 'dateTime':
        case 'dateRange':
        case 'timeRange': 
          if(param[key] && Array.isArray(param[key]) && param[key].length){
            param[`${key}%`] = param[key];
            delete param[key];
          }
        break;
        case 'text':
          param[`${key}$`] = `%${param[key]}%`;
          delete param[key];
        break;
        default:
          switch(typeof param[key]){
            case 'string': 
              if(!format && !enumList){
                param[`${key}$`] = `%${param[key]}%`;
                delete param[key];
              }
            break;
            case 'object':
              if(Array.isArray(param[key]) && enumList){
                param[key] = param[key].sort().join(',');
              }
          }
      }
    }

  }

  return param;

}


/**
 * 根据children 列表集合生成key 
 * 例：[{ name: 11, children: [{ name: 222 }]}]
 * [{ field: "FormData", children: [{ field: FormData[0].children}] }]
 */
export function generateFormListKeys(data, prefix = ''): FormListField[] {
  const result = [];

  data.forEach((item, index) => {
      const obj:FormListField  = { key: getUuid(), field: prefix }
      if (item.children && item.children.length > 0) {
        const key = `${prefix}[${index}]`;
        obj.children = generateFormListKeys(item.children, key + '.children');
      }
      result.push(obj);
  });

  return result;
}

/**
 * 从多层级中删除指定key 参数
 */
export function removeItemByFormList(arr: FormListField[], keyToRemove) {
  return arr.filter(item => {
    return item.key !== keyToRemove;
  }).map((item, index) => {
    if(item.pField){
      item.field = `${item.pField}.children`;
    }
    if(item.children) {
      item.children.forEach((o) => o.pField = `${item.field}[${index}]`);
      item.children = removeItemByFormList(item.children, keyToRemove);
      if(!item.children.length){
        delete item.children;
      }
    }
    return item;
  });
}


/**
 * 多层级数据添加
 */
export function addItemByFormList(arr: FormListField[], keyToAdd: string){
  for (const index in arr) {
    const item = arr[index];
    if(item.key === keyToAdd){
      arr.splice(Number(index) + 1, 0, {
        field: item.field,
        key: getUuid(),
      })
      break;
    }
    if(item.children){
      addItemByFormList(item.children, keyToAdd);
    }
  }
}



/**
 * @$ref 获取$ref 对应的schema 值
 */
export function getRefSchema($ref, schema): [any, string[]] {
  const paths = $ref.split('/').slice(1);
  return [_.get(schema, paths), paths];
}