import React, { useMemo, useState } from 'react';
import type { JSONSchemaCustom } from 'src/components/schema/interface';
import { Button, Form, FormProps, Modal } from '@arco-design/web-react';
import _ from 'lodash';
import FormGeneragte, { FormGeneragteProps } from "src/components/FormGenerate";
import { getRefSchema, schemaToFormItem } from 'src/utils/form';


export interface EidtRefSchemaProps {
    parentKey: string;
    form: FormProps['form'];
    $ref: string;
    schema: JSONSchemaCustom;
    value?: any;
    onChange?: (value) => void;
}
const EidtRefSchema = (props: EidtRefSchemaProps) => {


    const schema: JSONSchemaCustom = useMemo(() => {
        const [s, paths] = getRefSchema(props.$ref, props.schema);
        if(s){
            const objSchema = _.cloneDeep(s);
            objSchema.title = objSchema.title || paths.pop();
            objSchema.definitions = _.cloneDeep(props.schema.definitions)
            return objSchema
        }
        return { type: "object", properties: {} };
    }, [])

    // cols={24}
    //                                     formItemList={forms.events}
    //                                     getLabelField={getLabelField}
    //                                     widgets={widgets}

    const formList = useMemo(() => {
        return schemaToFormItem(schema)
    },[schema])


    return (
        <FormGeneragte
            form={props.form}
            formItemList={formList}
            fieldKey={props.parentKey}
        />
    )
}

export default EidtRefSchema;