import React, { useRef, useState, useCallback, HTMLProps, useMemo, ReactElement, JSXElementConstructor } from 'react';
import ContentStore from 'src/components/container/store';
import { useObserver } from 'mobx-react-lite';
import { toJS } from 'mobx';
import moduleStore from 'src/store/moduleStore';
import { get as safeGet, set as safeSet } from "lodash";
import { getBuilderItems, getDataBuilder, getExpressionData, getTranslations } from 'src/utils/builder';
import _ from 'lodash';
import { ListItem } from 'src/components/CustomPage/interface';


interface DropDragViewProps extends HTMLProps<HTMLDivElement> {
  contentData: ContentStore;
  item: ListItem;
  Element?: JSXElementConstructor<any>;
}
// 添加拖动属性
export default ({
  contentData,
  item,
  children,
  ...props
}: DropDragViewProps) => {

	return useObserver(() => {

        const propsData = useMemo(() => {
            return getTranslations(contentData, toJS(item.props));
        },[item.props])
        const builders = useMemo(() => {
            return getBuilderItems(toJS(propsData), item.key);
        },[propsData])

        const Element = useMemo(() => {
            const { render } = moduleStore.elements.get(item.key);
            return render;
        },[])

		/**
		 * 克隆 传入children 组件，将设置props 属性传入
		 */
		const props = useMemo(() => {
			let props = { ...propsData }
			// 对引用的值进行解析
			props = getDataBuilder(props, builders, contentData)
			// 根据schema类型，对返回值进行修改
			props = moduleStore.getModuleProps(item.key, props, contentData);
			if('ref' in props){
				props.ref = props.ref? contentData.$refs[props.ref] : undefined;
			}
			return { ...props } as any
		},[propsData, builders.map((o) => safeGet(contentData, o.path))])
		// console.log(`${item.id}-${item.key}`, _.cloneDeep(props), propsData);


        if(children){
            return (
                <Element {...props}>
                    {children}
                </Element>
            )
        }
        return (
            <Element {...props} />
        )

	})
};
