import type { pageDataProps } from "src/components/CustomPage/interface";
import { isJsxString } from "src/utils/is";
import { jsStringToJs, jsTojsString, tsTojsString } from "src/utils/js";
import config from "src/config";

/**
 * 页面或组件全局
 */
class Store {

    [x: string]: any;
    _custom_prototype: Store;
    
    /**
     * 页面map 变量，会重复
     */
    _arguments = {};

    page: pageDataProps['page'];
    
    
    // 写入constructor
    getConstructor(){
        const { constructorStr } = this.page;
        if(constructorStr && constructorStr.startsWith('constructor')) return constructorStr;
        return `constructor(){\n\tmakeAutoObservable(this);\n}\n`
    }

    // 写入vars 变量
    getVarText(){
        const { vars = [] } = this.page;
        let text = '';
        for (const item of vars) {
            const { name, type, value, description } = item;
            if(name){
                if(isJsxString(value)) {
                    text += `${name}${type? `:${type}` : ''} = ${jsStringToJs(value)};\n\n`;
                }else {
                    text += `${name}${type? `:${type}` : ''} = ${JSON.stringify(value)};\n\n`;
                }
            }
        }

        return text;
    }

    // 写入methods
    getMethodText(){
        const { methods = [] } = this.page;
        let text = '';
        for (const item of methods) {
        const { name, value, description } = item;
        if(value && name){
            if(isJsxString(value)) {
            text += `${name} = ${jsTojsString(value)}\n\n`;
            }else {
            text += `${name} = ${value}\n\n`;
            }
        }
        }
        return text;
    }

    // 写入computed
    getComputedText(){
        const { computeds = [] } = this.page;

        let text = "";

        if(computeds){
            for (const comput of computeds) {
                const { name, value, description } = comput;
                if(value && name){
                if(value) {
                    text += `get ${name}()${value}\n\n`;
                }
                }
            }
        }

        return text;
    }



    constructor({ page }: Partial<pageDataProps>){
        this.page = page;
    }



    getStoreText = (isStore: boolean = false) => {
              
        // _arguments 这个特性只有在开发环境存在
        const storeStr = `
            class Store { \n\n

                ${this.getVarText()}

                ${this.getConstructor()}

                ${this.getMethodText()}

                ${this.getComputedText()}
                ${isStore? this.getUseMemoToCompute() : ''}

            }
        `

        return tsTojsString(storeStr).outputText;
    }

    loadUseMemos = (store: any) => {
        const { useMemos } = this.page;

    }

    getPageToIndexArguments = () => {
        const { vars = [], computeds = [], methods = [] } = this.page;
        const keys = [
          ...vars.filter((o) => o.name).map((o) => o.name),
          ...computeds.filter((o) => o.name && o.value).map((o) => o.name),
          ...methods.filter((o) => o.name && o.value).map((o) => o.name),
        ]
        return keys.join(' , ');
    }
    
    /**
     * 模拟useMemo 参数
     */
    getPageFunctionToArguments = () => {
        const { vars = [], computeds = [], methods = [], useMemos = [] } = this.page;
        const keys = [
          ...vars.filter((o) => o.name).map((o) => o.name),
          ...computeds.filter((o) => o.name && o.value).map((o) => o.name),
          ...methods.filter((o) => o.name && o.value).map((o) => o.name),
          ...useMemos.filter((o) => o.name && o.value).map((o) => o.name),
        ]
        return keys.join(' , ');
    }

    /**
     * 由get 注入
     */
    getUseMemoToCompute = () => {
        const props = {};
        const { useMemos } = this.page;

        let text = "";

        console.log('useMemos', useMemos)
        if(useMemos){
            for (const comput of useMemos) {
                const { name, value, isFunctionNode, functionNode} = comput;
                if(isFunctionNode){
                    if(name && functionNode && functionNode.jsxBody){
                        const { countList, jsxBody } = functionNode;
                        const getVar = () => {
                            if(countList && countList.length){
                                return countList.filter((o) => o.countName).map((o) => {
                                    return `const ${o.countName} = ${o.countValue}`;
                                }).join('\n')
                            }
                            return "";
                        }
                        text += `get ${name}(){
                            const props = {};
                            const store = this;
                            const { ${this.getPageToIndexArguments()} } = store;
                            ${getVar()}

                            return ${jsxBody}
                        }\n\n`;
                    }
                }else {
                    if(name && value){
                        if(value) {
                            text += `get ${name}(){
                                const props = {};
                                const store = this;
                                const { ${this.getPageToIndexArguments()} } = store;
                                return (${value})();
                            }\n\n`;
                        }
                    }
                }
            }
        }

        return text;
    }

    getStore(){
        const storeText = this.getStoreText(true);

        const fun = new Function(`globals`, `
            const { ${Object.keys(config.run).join(',')} } = globals;

            ${storeText};

            return new Store();
        `)
        

        try {
            const store = fun(config.run);
            store._custom_prototype = this;
            return store;
        }catch(e) {
            console.error("store 文件格式错误", e);
            class Store {
                _arguments = {};
            }
            
            return new Store();
        }
    }
}


export default Store;