import React, { useRef, useState, useCallback, HTMLProps, useMemo, ReactElement, JSXElementConstructor } from 'react';
import { useDrag, useDrop } from 'react-dnd';
import classnames from 'classnames';
import PageStore from '../../store';
import ContentStore from 'src/components/container/store';
import Store from './store';
import { ListItem, ModuleItem, insertPosition } from '../../interface';
// import { useObserver } from 'mobx-react';;
import { Placeholder } from '../DropView';
import { useObserver } from 'mobx-react-lite';;
import { toJS } from 'mobx';
import moduleStore from 'src/store/moduleStore';
import { moduleDisplay, moduleSource } from 'src/types/module';
import MyErrorBoundary from 'src/components/custom/MyErrorBoundary';
import { identity, get as safeGet, set as safeSet } from "lodash";
import { getDataBuilder, getExpressionData } from 'src/utils/builder';
import _ from 'lodash';
import { createCustomNode } from 'src/components/container/CustomContent';
import { executeJsCode } from 'src/utils/function';
import ContextMenu from '../ContextMenu';
import { Button } from '@arco-design/web-react';
import { IconArrowDown, IconArrowUp, IconCopy, IconDelete, IconMessage, IconSettings, IconStar } from '@arco-design/web-react/icon';
const { Group: ButtonGroup } = Button;

interface DropDragViewProps extends HTMLProps<HTMLDivElement> {
  pageStore: PageStore;
  contentData: ContentStore;
  item: ListItem;
  Element?: JSXElementConstructor<any>;
}
// 添加拖动属性
export default ({
  pageStore,
  contentData,
  item,
  children,
  ...props
}: DropDragViewProps) => {

	const [store] = useState(() => {
		// 当前组件未添加时，注册组件Store
		if(!pageStore.mapStore.has(item.id)){
			pageStore.mapStore.set(
				item.id,
				new Store({
					props: item.props, 
					key: item.key,
					id: item.id,
					page: pageStore,
				})
			)	
		}
		return pageStore.mapStore.get(item.id);
	})
	const [
		isContainer, isInline, extraInfo, nickname, source,
		Element
	] = useMemo(() => {
		// 判断是否为内联元素
		const { display, props = {}, nickname, extraInfo = {}, source, content, render } = moduleStore.elements.get(item.key)
		let E: any = render;
		const { isOriginal, isModal } = extraInfo
		if(isOriginal && content){
			const { list, page } = content;
			E = createCustomNode({ list, page })
		}
		// if(components && Array.isArray(components)){
		// 	if(components.includes('basics_if') || components.includes('basics_for')){
		// 		const { list, page } = content;
		// 		E = createCustomNode({ list, page })
		// 	}
		// }
		const { children } = props.properties || {};
		// 是否可以拖动
		const isChildren = (children && children.format !== 'node') || source == "context";
		return [
			// 如果存在 children 且 childDrag 开启 则可以认为可以添加子元素
			isChildren && pageStore.childDrag,
			// 判断是否为内联元素
			display === 'inline',
			extraInfo || {},
			nickname,
			source,
			isModal? (props) => <div {...props} /> : E
		];
	},[])
	return useObserver(() => {

		const ref = useRef(null);
		const { isTop, mode, setIsTop, setMode } = store;
		const [, drag] = useDrag({
			type: pageStore.type,
			item,
			options: {
				dropEffect: 'move',
			},
			canDrag: (monitor) => {
				// console.log('canDrag', monitor)
				// 副作用会影响到当前的布局，所以先移出副作用
				if(pageStore.parse) pageStore.parse.clearEffect();
				// 当前组件在拖动
				pageStore.setMoveId(item.id);
				return true;
			},
			end: () => {
				// 组件拖动结束
				pageStore.setMoveId('');
			},
		});

		const [[isOver, oItem], drop]: any = useDrop({
			accept: pageStore.type,
			drop: (data: ModuleItem | ListItem, monitor) => {
				const bool = monitor.didDrop();
				if (bool) return;
				// 存在id，则确定为修改组件位置
				// console.log('console.log',data, item.id, store.position)
				// 副作用会影响到当前的布局，所以先移出副作用
				if(pageStore.parse) pageStore.parse.clearEffect();
				if ('id' in data) {
					// 判断当前容器接收到的组件是否不一致
					if (data.id === item.id) return;
					// 更新元素
					pageStore.updateList(data, item.id, store.position);
				} else {
					// 添加元素 通过mode判断当前组件拖动位置，是否作为容器子类还是相临组件进行插入
					pageStore.addList(data, item.id, store.position);
				}
			},
			collect: (monitor) => {
				const data = monitor.getItem<ListItem>();
				// 判断当前接收组件id 和传入id是否一致
				const notOneself = !data || item.id !== data.id;
				return [monitor.isOver({ shallow: true }) && notOneself, data];
			},
		});
		drop(drag(ref));


		const props = useMemo(() => {
			return store.domProps;
		},[store.props])
		// console.log(`props-${item.id}-${item.nickname || item.name}`, store.props, props, store.isDynamicData);

		/**
		 * @name 通过DrapOver方法，获取当前拖动所属容器
		 */
		const onDragOver = useCallback((e:any, bool = false) => {
			// console.log('onDragOver', item.key)
			const mouseY = e.clientY;
			const { top, height } = e.currentTarget.getBoundingClientRect();
			const centerY = top + height / 2;
			if (mouseY < centerY) {
				// 上半部分
				setIsTop(true);
			} else {
				// 下半部分
				setIsTop(false);
			}
			if(mode !== bool) setMode(bool);
			e.preventDefault();
			e.stopPropagation();
		},[mode])

		const domProps: HTMLProps<HTMLDivElement> = useMemo(() => {
			return {
				ref: ref,
				onDragOver: onDragOver,
				onClick: (e) => {
					e.stopPropagation();
					e.preventDefault();
					if(pageStore.selectId != item.id){
						// 有可能props 会更新
						if(pageStore.parse) pageStore.parse.init(ref.current);
					}
					// 选中组件
					pageStore.setSelectId(item.id)
				},
				onDoubleClick: (e) => {
					if(pageStore.onDoubleClick){
						pageStore.onDoubleClick(
							moduleStore.elements.get(item.key)
						);
					}
					e.stopPropagation();
				},
				onMouseEnter: () => {
					if(pageStore.parse) pageStore.parse.mouseHtml(ref.current);
				},
				onMouseLeave: () => {
					if(pageStore.parse) pageStore.parse.mouseoutHtml(ref.current);
				},
				onContextMenu: (e) => {
					// 这里是为了右键菜单内容修复
					e.stopPropagation();
				},
				className:classnames({
					['drop-page-view']: true,
					['move-container']: pageStore.moveId === item.id,
					['drop-page-isInline']: isInline
				}, extraInfo.className)
			}
		},[mode, pageStore.moveId])

		// console.log('children', children);

		const isSelected = pageStore.selectId === item.id;

		const renderProps = {
			onDragOver:(e) => {
				// console.log('onDragOver')
				onDragOver(e, true)
			},
			className: classnames({
				['drop-page-container-view']: true,
				['container-event']: extraInfo.isEvents,
				// [styles.pointerEvents]: true,
				// [styles.dropViewHover]: isOver && mode,
				['drop-select-bool']: isSelected
			})
		}

		/** 快捷操作 */
		const onClickItem = useCallback((key, e?:any) => {
			if(e){
				e.stopPropagation();
			}
			switch(key){
				case "copy":
					pageStore.copyList(item.id);
				break;
				case "delete":
					pageStore.deleteList(item.id);
				break;
				case "prev":
				case "next":
					const result = pageStore.list.filter((o) => o.parentId === item.parentId); // 获取当前同层级数据
					const index=  result.findIndex((o) => o.id === item.id);
					if(key === "prev"){
						if(index > 0){
							pageStore.updateList(item, result[index-1].id, insertPosition.prev);
						}
					}else if(key === "next"){
						const index = result.findIndex((o) => o.id === item.id);
						if(index < (result.length - 1)){
							pageStore.updateList(item, result[index+1].id, insertPosition.next);
						}
					}
				break;
					
			}
		},[])

		const tooltipRender = useMemo(() => {
			if(!isSelected) return null;
			return (
				<ButtonGroup className={'drop-page-tooltip'}>
					<Button 
						size="mini" type='primary' icon={<IconCopy />}
						onClick={(e) => onClickItem("copy", e)}
					/>
					<Button
						size="mini" type='primary' icon={<IconDelete />}
						onClick={(e) => onClickItem("delete", e)}
					/>
					<Button
						size="mini" type='primary' icon={<IconArrowUp />}
						onClick={(e) => onClickItem("prev", e)}
					/>
					<Button 
						size="mini" type='primary' icon={<IconArrowDown />}
						onClick={(e) => onClickItem("next", e)}
					/>
				</ButtonGroup>
			)
		},[isSelected])

		let MainRender: any = null;
		if(store.portal){
			const renderElement = (
				<div {...renderProps}>
					<div className={'drop-page-namespace'}>{nickname || item.name}</div>
				{/* <div className={'drop-page-namespace'}>{!isNotDrop && namespace}</div> */}
					{props.children}
					{children}
					{(isOver && mode) && <Placeholder />}
				</div>
			);
			MainRender =  (
				// <Element {...props}>
					<div {...domProps}>
						{isOver && (!mode && isTop) && <Placeholder />}
						{isContainer && renderElement}
						{isOver && (!mode && !isTop) && <Placeholder />}
						{tooltipRender}
					</div>
				// </Element>
			)
		}else {
			// 当前组件内容元素
			const renderElement = (
				<div {...renderProps}>
					<div className={'drop-page-namespace'}>{nickname || item.name}</div>
					<MyErrorBoundary>
						{store.isFunctionNode? 
							<Element {...props} >
								{(...args) => {
									const list: any[] = React.Children.toArray(children);
									const contentStore: any = Object.create(contentData);
									contentStore._arguments = {
										...contentStore._arguments,
									}
									if(Array.isArray(store.funParams)){
										for (let i = 0; i < store.funParams.length; i++) {
										contentStore._arguments[store.funParams[i]] = args[i];
										}
									}
									const { varName, varBody } = props.children || {};
									if(varName && varBody){
										contentStore._arguments[varName] = executeJsCode(varBody, contentData);
									}
									// 合并函数变量
									Object.assign(contentStore, contentStore._arguments);
									const childrenRender = list.map((Element, j) => {
										if(!Element.props.contentData) return Element;
	
										return React.cloneElement(Element, {
											contentData: contentStore
										})
									});
									return (
										<React.Fragment>
											{childrenRender}
											{(isOver && mode) && <Placeholder />}
										</React.Fragment>
									)
								}}
							</Element>
							: (
							<Element {...props}>
								{props.children}
								{children}
								{(isOver && mode) && <Placeholder />}
							</Element>
						)}
					</MyErrorBoundary>
				</div>
			);
			MainRender = (
				<div {...domProps}>
					{isOver && (!mode && isTop) && <Placeholder style={{ marginTop: -6, marginBottom: 2 }} />}
					{isContainer ? renderElement : (
						<div
							className={classnames({
								['drop-page-container-view']: true,
								['container-event']: extraInfo.isEvents,
								['drop-select-bool']: isSelected
							})}
						>
							<div className={'drop-page-namespace'}>{nickname || item.name}</div>
							<MyErrorBoundary>
								<Element {...props} />
							</MyErrorBoundary>
						</div>
					)}
					{tooltipRender}
					{isOver && (!mode && !isTop) && <Placeholder style={{ marginBottom: -6, marginTop: 2 }} />}
				</div>
			);	
		}

		const menuItems = useMemo(() => {
			return [
				{
					key: 'copy',
					text: '复制',
				},
				{
					key: 'delete',
					text: '删除',
				},
				{
					key: "prev",
					text: "上移",
				},
				{
					key: "next",
					text: "下移",
				},
			]
		},[])

		/**
		 * 最终渲染
		 */
		return (
			<ContextMenu
				onClickItem={onClickItem}
				items={menuItems}
			>
				{MainRender}
			</ContextMenu>
		)
	})
};
