import React, { useRef, useCallback, memo, useMemo, useState, useEffect, useContext } from 'react';
// import styles from './index.module.less';
import moduleStore from 'src/store/moduleStore';
import { useLocalStore, useObserver } from 'mobx-react-lite';
import type { ListItem, pageDataProps, pageProps } from 'src/components/CustomPage/interface';
import Store from 'src/components/container/store';
import { getBuilderItems, getDataBuilder, getExpressionData } from 'src/utils/builder';
import { ForProps } from 'src/types/control';
import MyErrorBoundary from 'src/components/custom/MyErrorBoundary';
import { executeJsCode, executeSandboxedCode } from 'src/utils/function';
import { NodeElementContext } from '../context';
import PageStore from '../../store';
import DropDragViewStore from '../../components/DropDragView/store';

interface ContentProps {
  store: Store;
  page?: pageDataProps['page'];
  list: pageDataProps['list'];
}

const basics = {
  basics_for: (fun: any, children: any[], props: ForProps, store: Store) => {
    const { each, of, index, varName, varBody } = props;
    if(!Array.isArray(of)){
      return null;
    }
    return of.map((item, i) => {
      const contentData: Store = Object.create(store);
      contentData._arguments = {
          ...contentData._arguments,
          [each || "item"]: item,
          [index || "index"]: i
      }
      if(varName && varBody){
        contentData._arguments[varName] = executeJsCode(varBody, contentData);
      }
      Object.assign(contentData, contentData._arguments);
      // console.log('contentData', store, contentData)
      
      return fun(children, contentData);
    })
  },
  basics_text: (fun: any, children: any[], props: any, store: Store) => {
    return props.value || null
  }
}

interface ElementUIProps {
  o: any;
  contentData: Store;
  pageStore: PageStore;
  getElementList: (a,b) => any[] | null;
}
const ElementUI = ({ o, pageStore, contentData, getElementList }: ElementUIProps) => {
  // console.log(o.key, o.props);
  // const Element = useMemo(() => {
  //   return moduleStore.elements.get(o.key).render;
  // },[])
  // const vars = getBuilderItems(o.props, o.key);

  const [element] = useState(() => moduleStore.elements.get(o.key));
  const ElementRender = element.render;
  const [store] = useState(() => {
    const mStore = new DropDragViewStore({ props: o.props, key: o.key, id: o.id, page: pageStore });
    // console.log('ElementUI-pageStore', pageStore)
    if(pageStore){
      // 当前组件未添加时，注册组件Store
      pageStore.mapStore.set(
        o.id,
        mStore
      )
    }
		return mStore;
  })
  // const vModel: string = o.props["v-model"];

  // console.log('vModel', vModel);
  return useObserver(() => {
    useMemo(() => {
      store.setProps({ ...store.props, ...o.props });
    },[o.props])
    // 动态监听props
    const props = useMemo(() => {
      return store.domProps;
    },[store.props])
    // console.log(o.key, props, o, contentData);

    // console.log("childrenRender", o, getElementList(o.children, contentData));
    
    let children = getElementList(o.children, contentData);
    if(typeof props.children !== "undefined"){
      // 系统中存在两种 children类型，一种在props 中作为参数进行传输，还有一个是children 是通过拖拽子类添加
      // 第一种目前针对的一般是 string 类型参数
      // 两种children 合并展示，否则在input 中返回多个 null 则会报错
      if(children) children.push(props.children);
      else children = props.children;
    }
    if(children && children.length === 1){
      // 例如 Tooltip组件，这种不支持ReactNode[] 所以单个组件不能使用数组进行添加
      children = children[0]
    }
    return (
      <ElementRender key={o.id} data-id={o.id} {...props}>
        {children}
      </ElementRender>
    );
  })
}

/**
 * 页面内容区域 web-container
 * @param width 750
 * @param height 900
 */
function Content({ store, list, page = {} }: ContentProps){

  const context = useContext(NodeElementContext);


  const children = useMemo(() => {
    const getElementList = (list, contentData: Store) => {
      if(!Array.isArray(list) || list.length === 0) return null;
      return list.map((o: any, i) => {
        if(basics[o.key]){
          const vars = getBuilderItems(o.props, o.key);
          const props = getDataBuilder(o.props, vars, contentData);
          // 控制器类型
          return basics[o.key](getElementList, o.children, props, contentData);
        }
        // return ElementUI({ 
        //   o,
        //   contentData,
        //   getElementList,
        // })
        return (
          <ElementUI
            key={i} o={o}
            contentData={contentData}
            getElementList={getElementList}
            pageStore={context.store}
          />
        )
      });
    }
    return getElementList(list, store);
  }, [list]);

  return (
    <MyErrorBoundary>
      {children}
    </MyErrorBoundary>
  );
};

export default Content;